import{z as l,x as A,o as r,c as p,q as n,j as t,D as e,d as i,s as E,S as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"广告：信息与说服","description":"","frontmatter":{"title":"广告：信息与说服","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/advertising-economics.md","filePath":"econ/advertising-economics.md","lastUpdated":1791413859000}'),B={name:"econ/advertising-economics.md"};function d(D,a,c,_,m,g){const o=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=n('<h1 id="广告-信息与说服" tabindex="-1">广告：信息与说服 <a class="header-anchor" href="#广告-信息与说服" aria-label="Permalink to &quot;广告：信息与说服&quot;">​</a></h1><div class="epigraph"><p>同一支广告，信息观里是免费的地图，说服观里是给偏好压模的手；回归分不清二者，是因为销量本身就在指挥广告预算。</p><footer>—— 据 Telser, Supply and Demand for Advertising Messages, AER 1966；Nelson, Advertising as Information, JPE 1974 整理</footer></div><p><a href="/econ/rnd-patent-races">上一课</a>把产品的时间维打开：技术换代以竞赛的方式进行，奖品由专利局定价。本课转向需求侧：即使技术不变，需求矩阵也不是天生给定的——广告是厂商花钱改写需求的最直接工具。微观主干的<a href="/econ/akerlof-lemons">柠檬市场</a>与<a href="/econ/information-intermediaries">信息中介</a>都假设消费者知道市场上有什么；广告正往这个假设上开口。本课把「广告是什么」压成三种可检验的读法，再回答一个测量问题：广告—销售回归为什么几乎读不出因果。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>广告开支巨大且高度集中，经济学要问的却窄：它改变需求的哪一层。三种读法给出了三套含义。其一，<strong>告知</strong>：Stigler 1961 的搜寻框架里广告降低找货成本，Telser 1966 的面板研究即循此路——广告是消费者对信息的需求与厂商对信息供给的均衡价格。其二，<strong>说服</strong>：广告改变口味；Stigler–Becker 1977 反对这个说法，把广告写成消费生产函数里的互补品——口味不变，「欣赏能力」在积累。其三，<strong>信号沉淀</strong>（Nelson 1974）：对经验品，广告本身不携带信息，但<strong>花钱</strong>携带——只有高质量、回头客多的厂商付得起这支广告，广告强度是质量的信号。第三读法直接接到下一课的声誉抵押。</p><p><span class="marginnote">术语翻译：搜寻品是货架上看一眼就能验货的东西（西红柿、衬衫）；经验品是买回用了才知道好坏的东西（牙膏、餐馆）。Nelson 的「花钱即信号」逻辑只对经验品要紧——搜寻品不需要回头客背书，广告直接报事实就够了。</span></p><p>内生出在制度里：预算按销售额的百分比走，广告又反过来推销售——联立性把 OLS 系数拧成混合体，同时含「广告推销售」与「销售指挥预算」两个方向。</p>',7)),(r(),t(s,null,{default:e(()=>[E(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADS%5B%22%E5%B9%BF%E5%91%8A%E6%94%AF%E5%87%BA%20a%22%5D%20--%3E%20D1%5B%22%E5%91%8A%E7%9F%A5%EF%BC%9A%E9%99%8D%E6%90%9C%E5%AF%BB%E6%88%90%E6%9C%AC%22%5D%0A%20%20ADS%20--%3E%20D2%5B%22%E8%AF%B4%E6%9C%8D%EF%BC%9A%E7%A7%BB%E5%8A%A8%E9%9C%80%E6%B1%82%22%5D%0A%20%20ADS%20--%3E%20D3%5B%22%E6%B2%89%E6%B7%80%EF%BC%9A%E8%B4%A8%E9%87%8F%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20D1%20--%3E%20DEM%5B%22%E9%9C%80%E6%B1%82%20D(p%2C%20a)%22%5D%0A%20%20D2%20--%3E%20DEM%0A%20%20D3%20--%3E%20DEM%0A%20%20DEM%20--%3E%20OLS%5B%22%E5%9B%9E%E5%BD%92%EF%BC%9A%E9%94%80%E5%94%AE%E6%8C%87%E6%8C%A5%E9%A2%84%E7%AE%97%20%E2%86%92%20%E7%B3%BB%E6%95%B0%E4%B8%8D%E5%8F%AF%E8%AF%BB%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p><span class="marginnote">Dorfman–Steiner 1954 的最优广告强度：广告支出占销售额之比 \\(=\\varepsilon_a/|\\varepsilon_p|\\)。数字例：需求的广告弹性 \\(0.1\\)、价格弹性 \\(2\\)，则最优广告/销售比为 \\(5\\%\\)。这是均衡关系，不是弹性的定义，拿它反推弹性要小心。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>识别的出路是找<strong>不由销售决定</strong>的广告变动：广告禁令（烟草、处方药的跨州差异）、媒体侧的外生变动（频道落地、报刊罢工）、平台侧的随机分流实验。设计上还要借品类结构：Ackerberg 2001 对新上市食品的追踪发现，信息型广告只对<strong>无消费经验</strong>的人群起作用，老顾客毫不动摇——这恰好把「告知」与「说服/沉淀」在同一数据里分开，是三读法的实证分水岭。另一条路是动态化：Roberts–Samuelson 1988 用香烟行业数据把广告写成商誉存量——支出积累一个缓慢折旧的 \\(G_t\\)，当期需求 \\(D(p_t, G_t)\\)；广告竞争于是是存量的军备，不是当期流量的比拼，与<a href="/econ/collusion-cartel">合谋</a>的耐心逻辑接得上。</p><p>错在哪：把广告支出当需求弹性用——Dorfman–Steiner 比式是厂商已经优化后的均衡关系，截面上「广告多的行业弹性大」读不出任何因果；把禁令效应直接当说服证据——禁令同时改了信息的可得性，告知读法也预言销量下降。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>三读法对福利的判断不同。告知读法下广告近于公共品的信息生产，可与社会最优对齐；说服读法下均衡广告超过最优——Dixit–Norman 1978 论证广告的自我实现：各家都做，需求被互相拉扯，社会付出真金白银却只换来份额重分；沉淀读法下广告是抵押的另一种资产形态（下一课的会计）。经验品配情感型内容、搜寻品配硬信息是稳定的经验规律；成熟市场的份额争夺比开发新客更贵，集中行业常常广告过密。</p>',6)),(r(),t(s,null,{default:e(()=>[E(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SP%5B%22%E5%BD%93%E6%9C%9F%E5%B9%BF%E5%91%8A%E6%94%AF%E5%87%BA%22%5D%20--%3E%20G%5B%22%E5%95%86%E8%AA%89%E5%AD%98%E9%87%8F%20G_t%20%E7%B4%AF%E7%A7%AF%22%5D%0A%20%20G%20--%3E%20DEM%5B%22%E9%9C%80%E6%B1%82%20D%20p_t%20G_t%22%5D%0A%20%20DEM%20--%3E%20PROF%5B%22%E5%88%A9%E6%B6%A6%E4%B8%8E%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20PROF%20--%3E%20SP2%5B%22%E5%8F%8D%E5%93%BA%E4%B8%8B%E4%B8%80%E6%9C%9F%E6%94%AF%E5%87%BA%22%5D%0A%20%20G%20--%3E%20DEP%5B%22%E6%8A%98%E6%97%A7%3A%20%E4%B8%8D%E6%8A%95%E5%B0%B1%E7%BC%93%E6%85%A2%E8%92%B8%E5%8F%91%22%5D%0A%20%20DEP%20--%3E%20SP%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<p><span class="marginnote">数字实例：商誉存量的月折旧率若为 10%，停投广告后 \\(G_t\\) 每月只剩九成，一年后存量只剩 \\(0.9^{12}\\approx 28\\%\\)。这解释了为什么广告一停销量是缓慢滑落而非立刻归零——需求里沉淀的商誉在折旧。</span></p><p>再补一条供给侧：广告密度高还可以是进入壁垒的形态——在位者用过量广告抬高新对手的获客成本，与<a href="/econ/limit-pricing">限制进入定价</a>同一时序。错在哪：把「广告是壁垒」或「广告是纯信息」说死。同一支广告可以同时降搜寻成本、移动偏好、沉淀抵押——三读法不是三选一，是三种可分别检验的边界条件。</p><p><span class="marginnote">直觉类比：Dixit–Norman 的自我实现像剧场里所有人起立看戏——站起来的人没有一个看得更清楚，但谁也不敢先坐下。各家广告互相抵消、只重分份额，可单家停投就会丢地盘，于是全体停在过量广告的均衡上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做广告创意与媒介策略，不评广告的社会文化外部性（儿童、成瘾品），那超出价格理论。平台广告的拍卖机制（关键词竞价）是双边市场课的邻居，这里只把广告当需求侧的变量。商誉存量的估计依赖折旧率假设；实验里平台分流的边际效应普遍小于回归文献的声称值——这本身就是内生性最好的注脚。后课默认：厂商可以花钱造需求，而造出来的需求自带可检验的形态约束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三读法：告知（降搜寻成本）、说服（移动需求）、沉淀（质量信号），可分别检验。</li><li>广告—销售回归内生：销售指挥预算，系数不可读作因果。</li><li>Dorfman–Steiner：广告/销售比 \\(=\\varepsilon_a/|\\varepsilon_p|\\)，是均衡关系不是定义。</li><li>商誉存量把广告竞争写成军备（Roberts–Samuelson）；均衡广告可超过最优（Dixit–Norman）。</li><li>出处：Telser 1966；Nelson 1974；Stigler–Becker 1977；Dixit–Norman 1978；Ackerberg 2001。</li></ul>',7))])}const S=l(B,[["render",d]]);export{f as __pageData,S as default};
